def calculate_discount(price, user_type, is_member, years_active):
    base_discounts = {'student': 0.2, 'senior': 0.15, 'regular': 0.0}
    member_bonuses = {'student': 0.05, 'senior': 0.05, 'regular': 0.1}
    loyalty_bonuses = {'student': 0.05, 'senior': 0.05, 'regular': 0.05}

    discount = base_discounts.get(user_type, 0)
    if is_member:
        discount += member_bonuses.get(user_type, 0)
    if years_active > 5:
        discount += loyalty_bonuses.get(user_type, 0)
    return price * (1 - discount)
